using System.Net;
using System.Text.Json;
using StardewThor.Bridge;
static class CatalogProgressContract {
 public static async Task Run(){int checks=0;void Check(bool ok,string name){if(!ok)throw new Exception(name);checks++;Console.WriteLine("PASS "+name);}using var server=new BridgeServer(0);server.Start();using var client=new HttpClient();string url=$"http://127.0.0.1:{server.Port}";server.CatalogItems=new("items");server.CatalogPeople=new("people");server.Progress=new(new PlayerProgress(1,Array.Empty<string>(),Array.Empty<string>(),new(0,0,0,0,0,0,0),new(),0,Array.Empty<string>(),"building","zh"),512*1024);
  using(var first=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items"))){Check(first.RootElement.GetProperty("state").GetString()=="building","catalog starts building");Check(first.RootElement.GetProperty("progress").GetProperty("done").GetInt32()==0,"catalog explicit generation progress");}Check(server.CatalogItems.Wanted&&!server.HasReader,"catalog owns independent game lease");
  var row=new CatalogItem("(O)24","防风草","运行时描述","蔬菜",-75,35,null,"object",null,true,new("cooking",new[]{new CatalogIngredient("-75",1)}));server.CatalogItems.Publish(new("items",4,"zh","ready",Enumerable.Range(0,101).Select(i=>(object)(row with{Id="(O)"+i})).ToArray(),new[]{"catalog-price-unsupported"}));
  foreach(var p in new[]{0,1}){using var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items?page="+p));var r=doc.RootElement;Check(r.GetProperty("entries").GetArrayLength()==(p==0?100:1),"catalog exact page size "+p);Check(r.GetProperty("total").GetInt32()==101&&r.GetProperty("pages").GetInt32()==2,"catalog paged totals "+p);Check(r.GetProperty("version").GetInt64()==4&&r.GetProperty("language").GetString()=="zh","catalog version/language "+p);}
  // Page digests on page 0, and a revision that follows the rows rather than each rebuild.
  string[] Digests(JsonElement r)=>r.GetProperty("digests").EnumerateArray().Select(d=>d.GetString()!).ToArray();
  string[] before;using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items"))){before=Digests(doc.RootElement);Check(before.Length==2&&before.All(d=>d.Length==16),"catalog page 0 carries a digest per page");}
  using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items?page=1")))Check(!doc.RootElement.TryGetProperty("digests",out _),"other catalog pages carry no digests");
  var rev=server.CatalogItems.Revision;server.CatalogItems.Publish(new("items",5,"zh","ready",Enumerable.Range(0,101).Select(i=>(object)(row with{Id="(O)"+i})).ToArray(),new[]{"catalog-price-unsupported"}));
  Check(server.CatalogItems.Revision==rev,"a rebuild with the same rows is not a catalogue change");
  server.CatalogItems.Publish(new("items",6,"zh","ready",Enumerable.Range(0,101).Select(i=>(object)(row with{Id="(O)"+i,Price=i==100?99:35})).ToArray(),new[]{"catalog-price-unsupported"}));
  Check(server.CatalogItems.Revision>rev,"a changed row is a catalogue change");
  using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items"))){var after=Digests(doc.RootElement);Check(after[0]==before[0]&&after[1]!=before[1],"only the changed page's digest moves");}

  using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items?page=81")))Check(doc.RootElement.GetProperty("state").GetString()=="out-of-range"&&doc.RootElement.GetProperty("entries").GetArrayLength()==0,"valid but absent page explicit out-of-range");
  var person=new CatalogPerson("secret","未知",null,"hiddenAlways",true,false,null,"Other",null,new(Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>(),Array.Empty<string>()));server.CatalogPeople.Publish(new("people",2,"zh","ready",new object[]{person},Array.Empty<string>()));using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/people"))){var e=doc.RootElement.GetProperty("entries")[0];Check(e.GetProperty("socialTab").GetString()=="hiddenAlways","native hiddenAlways preserved");Check(!e.TryGetProperty("relations",out _),"relations absent instead of fabricated");Check(e.GetProperty("birthday").ValueKind==JsonValueKind.Null&&e.GetProperty("portrait").ValueKind==JsonValueKind.Null,"unknown birthday/portrait remain null");}
  foreach(var path in new[]{"/v1/catalog/items?page=-1","/v1/catalog/items?page=82","/v1/catalog/people?page=6","/v1/catalog/items?page=01","/v1/catalog/items?page=1&page=2","/v1/catalog/items?limit=1000","/v1/catalog/items/","/v1/catalog/other"})Check((await client.GetAsync(url+path)).StatusCode==HttpStatusCode.BadRequest,"strict catalog route "+path);
  foreach(var path in new[]{"/v1/catalog/items?page=%31","/v1/catalog/../items"}){using var raw=new System.Net.Sockets.TcpClient();await raw.ConnectAsync("127.0.0.1",server.Port);var stream=raw.GetStream();await stream.WriteAsync(System.Text.Encoding.ASCII.GetBytes("GET "+path+" HTTP/1.1\r\nHost: localhost\r\n\r\n"));using var reader=new StreamReader(stream);Check((await reader.ReadLineAsync())!.Contains("400 Bad Request"),"encoded and traversal raw socket route "+path);}
  Check((await client.PostAsync(url+"/v1/catalog/items",new StringContent("{}"))).StatusCode==HttpStatusCode.MethodNotAllowed,"catalog rejects POST");Check((await client.PostAsync(url+"/v1/progress",new StringContent("{}"))).StatusCode==HttpStatusCode.MethodNotAllowed,"progress rejects POST");
  var progress=new PlayerProgress(7,new[]{"Abigail"},new[]{"(O)24"},new(1,0,0,0,0,0,0),new(){{"Valley",true},{"GingerIsland",false}},3,new[]{"map-condition-random"},"ready","zh");server.Progress.Publish(progress);using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/progress"))){var p=doc.RootElement;Check(p.GetProperty("knownItems")[0].GetString()=="(O)24","progress qualified ID");Check(!p.GetProperty("mapAreas").GetProperty("GingerIsland").GetBoolean(),"progress genuine unknown area flag");Check(p.GetProperty("itemSources").GetProperty("shipped").GetInt32()==1,"progress source counts");}Check(server.Progress.Wanted&&!server.HasReader,"progress own lease independent snapshot");
  var live=server.AddAsset(new byte[]{1,2,3});for(int i=0;i<255;i++)server.AddAsset(BitConverter.GetBytes(i));string? catalog=null;for(int i=0;i<300;i++)catalog=server.AddCatalogAsset(BitConverter.GetBytes(i+1000));Check(catalog!=null,"catalog assets survive full live cache");Check((await client.GetByteArrayAsync(url+live.Replace("/bridge/","/v1/"))).SequenceEqual(new byte[]{1,2,3}),"catalog cannot evict live asset");Check((await client.GetAsync(url+catalog!.Replace("/bridge/","/v1/"))).IsSuccessStatusCode,"catalog hash uses existing asset channel");Check(server.AddCatalogAsset(new byte[BridgeServer.CatalogAssetMax+1])==null,"catalog blob size cap");server.ClearAssets();Check((await client.GetAsync(url+catalog.Replace("/bridge/","/v1/"))).IsSuccessStatusCode,"live reset preserves catalog blobs");server.ClearCatalogAssets();Check((await client.GetAsync(url+catalog.Replace("/bridge/","/v1/"))).StatusCode==HttpStatusCode.NotFound,"catalog explicit invalidation removes catalog blobs");
  server.CatalogItems.Publish(new("items",9,"zh","ready",Enumerable.Range(0,100).Select(i=>(object)(row with{Id="(O)"+i,Description=new string('界',10000)})).ToArray(),Array.Empty<string>()));using(var doc=JsonDocument.Parse(await client.GetStringAsync(url+"/v1/catalog/items")))Check(doc.RootElement.GetProperty("state").GetString()=="unsupported"&&doc.RootElement.GetProperty("limited")[0].GetString()=="response-bytes","catalog response byte cap explicit");
  Console.WriteLine(checks+" catalog/progress contract checks passed");
 }
}
